  'AP Projection \u2014 Bilateral AC Joints: Pearson Method (With and Without Weights)': 'AC_Joints_AP_Bilateral_Pearson_Method_Bilateral',
  // ── Scapula ──
  'AP Projection \u2014 Scapula': 'Scapula_AP_Projection',
